import { Section } from './ui.jsx'
import { learns } from '../content.js'

/**
 * Learns: one person's usual day as a band, and today drawn against it. This is synthetic data,
 * generated by the formulas below for this page, and it is labelled as such on screen. It exists to
 * show the idea ("normal is personal, and judged hour by hour"), not to claim a result.
 *
 * Text is HTML, not SVG, so it stays readable when the chart scales down on a phone.
 */
const W = 640
const H = 280
const H0 = 6 // chart starts at 6am
const H1 = 22 // and ends at 10pm
const FLAG_H = 14.5 // when today is noticed (2:30pm)

const x = (h) => ((h - H0) / (H1 - H0)) * W
const y = (v) => 256 - Math.max(0, Math.min(1.08, v)) * 170 // headroom above the peak for the callout
const bump = (h, mu, sig, amp) => amp * Math.exp(-((h - mu) ** 2) / (2 * sig * sig))

// The usual movement at hour h, 0 to 1: a morning walk, lunch, an afternoon walk, a quiet evening.
const usual = (h) => 0.08 + bump(h, 8.5, 0.9, 0.62) + bump(h, 12.5, 0.7, 0.3) + bump(h, 15.5, 1.0, 0.66) + bump(h, 19, 0.8, 0.26)
const lo = (h) => usual(h) * 0.68 - 0.02
const hi = (h) => usual(h) * 1.32 + 0.05

// Today: follows the usual day, then drops well below it from 2pm.
const slow = (h) => Math.max(0, Math.min(1, (h - 13.75) / 0.5)) // 0 before 1:45pm, 1 after 2:15pm
const today = (h) => usual(h) * (1 + 0.1 * Math.sin(h * 7.3)) * (1 - slow(h) * 0.62)

const STEPS = Array.from({ length: (H1 - H0) * 4 + 1 }, (_, i) => H0 + i / 4)
const line = (fn, hs) => hs.map((h, i) => `${i ? 'L' : 'M'}${x(h).toFixed(1)} ${y(fn(h)).toFixed(1)}`).join(' ')
const BAND = `${line(hi, STEPS)} ${line(lo, [...STEPS].reverse()).replace('M', 'L')} Z`
const ON_ROUTE = line(today, STEPS.filter((h) => h <= FLAG_H))
const STRAYED = line(today, STEPS.filter((h) => h >= FLAG_H))
const FLAG = { x: x(FLAG_H), y: y(today(FLAG_H)) }

const TICKS = ['6 am', '10 am', '2 pm', '6 pm', '10 pm']

export default function Learns() {
  return (
    <Section id="learns" heading={learns.heading}>
      <p className="lede max-w-2xl">{learns.lede}</p>

      <figure className="mt-12 max-w-4xl">
        <p className="mb-3 text-base font-bold text-ink">{learns.axis}</p>
        <div className="relative aspect-[640/280] w-full">
          <svg viewBox={`0 0 ${W} ${H}`} className="absolute inset-0 h-full w-full" role="img" aria-label={learns.alt}>
            {/* gridlines at the tick hours */}
            {[10, 14, 18].map((h) => (
              <line key={h} x1={x(h)} x2={x(h)} y1="8" y2="256" stroke="var(--color-rule)" strokeWidth="1.5" />
            ))}
            <line x1="0" x2={W} y1="256" y2="256" stroke="var(--color-ink)" strokeWidth="2" />
            {/* the usual range, learned */}
            <path d={BAND} fill="var(--color-route-soft)" stroke="var(--color-route)" strokeWidth="1.5" />
            {/* today: ink while it follows the usual day, magenta once it has strayed */}
            <path d={ON_ROUTE} fill="none" stroke="var(--color-ink)" strokeWidth="4.5" strokeLinecap="round" strokeLinejoin="round" />
            <path d={STRAYED} fill="none" stroke="var(--color-stray)" strokeWidth="4.5" strokeLinecap="round" strokeLinejoin="round" />
            <circle cx={FLAG.x} cy={FLAG.y} r="14" fill="var(--color-paper)" stroke="var(--color-stray)" strokeWidth="4" />
            <circle cx={FLAG.x} cy={FLAG.y} r="4.5" fill="var(--color-stray)" />
          </svg>
          <p
            className="sign absolute -translate-x-1/2 whitespace-nowrap rounded-card bg-paper px-2 py-1 text-base text-stray ring-2 ring-stray"
            style={{ left: `${(FLAG.x / W) * 100}%`, top: '2%' }}
          >
            {learns.callout}
          </p>
        </div>
        <div className="sign mt-2 flex justify-between text-base text-muted" aria-hidden="true">
          {TICKS.map((t) => <span key={t}>{t}</span>)}
        </div>

        <ul className="mt-6 flex flex-wrap gap-x-8 gap-y-3 text-base">
          <li className="flex items-center gap-2"><span aria-hidden="true" className="h-4 w-8 rounded-[3px] border-2 border-route bg-route-soft" />{learns.legend[0]}</li>
          <li className="flex items-center gap-2"><span aria-hidden="true" className="h-1 w-8 rounded-full bg-ink" />{learns.legend[1]}</li>
          <li className="flex items-center gap-2"><span aria-hidden="true" className="h-1 w-8 rounded-full bg-stray" />{learns.legend[2]}</li>
        </ul>
        <figcaption className="mt-6 max-w-2xl text-base text-muted">{learns.note}</figcaption>
      </figure>
    </Section>
  )
}
